import os
import torch
import random
import numpy as np
from vllm import LLM, SamplingParams
from form_icl_demonstrations import SYSTEM_PROMPT
from transformers import AutoModelForCausalLM, AutoTokenizer
os.environ['VLLM_WORKER_MULTIPROC_METHOD'] = 'spawn'

def setup_seed(seed: int = 0):
    os.environ['PYTHONHASHSEED'] = str(seed)
    os.environ['CUBLAS_WORKSPACE_CONFIG'] = ':4096:8'  # For PyTorch 1.8+
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)
    np.random.seed(seed)
    random.seed(seed)
    torch.backends.cudnn.benchmark = False
    torch.backends.cudnn.deterministic = True
    torch.use_deterministic_algorithms(True)

def vllm_call(model, messages):
    outputs = model.generate(messages, sampling_params=SamplingParams(max_tokens=1024))
    for output in outputs:
        prompt = output.prompt
        generated_text = output.outputs[0].text
        print(f"Prompt: {prompt!r}\nGenerated text: {generated_text!r}")
        print(len(output.outputs[0].token_ids))
        print("-" * 50)

